from pathlib import Path
from playwright.sync_api import sync_playwright
import json, sys

ROOT=Path(__file__).resolve().parents[1]
html=(ROOT/'frontend/index.html').read_text()
# Stub pywebview before inline scripts execute. Every API call returns a harmless failure payload.
stub="""<script>window.pywebview={api:new Proxy({}, {get:()=>async()=>({ok:false,message:'render-audit stub'})})};</script>"""
html=html.replace('<head>','<head>'+stub,1)
checks={}
shots=ROOT/'ui-audit'
shots.mkdir(exist_ok=True)

def activate(page, page_id, pane=None):
    page.evaluate("""([pageId,pane])=>{document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));let p=document.getElementById(pageId);if(p){p.hidden=false;p.classList.add('active')}document.querySelectorAll('.analytics-pane').forEach(x=>x.classList.remove('active'));if(pane){let q=document.querySelector(`.analytics-pane[data-analytics-pane="${pane}"]`);if(q)q.classList.add('active')}}""", [page_id,pane])
    page.wait_for_timeout(50)

with sync_playwright() as pw:
    browser=pw.chromium.launch(headless=True,executable_path='/usr/bin/chromium',args=['--no-sandbox'])
    page=browser.new_page(viewport={'width':1568,'height':959})
    errors=[]
    page.on('pageerror',lambda e: errors.append(str(e)))
    page.set_content(html,wait_until='load')
    page.wait_for_timeout(150)

    # 0.9.5 frontend-critical runtime is independent of backend completion.
    clock_start=page.evaluate("""()=>{startUiRuntimeTimers();let first=dashboardClockTimer;startUiRuntimeTimers();return {same:first===dashboardClockTimer,clock:document.getElementById('dashClockLocalText')?.textContent||'',second:document.getElementById('dashClockLocalSecond')?.style.transform||'',countdown:!!pollCountdownTimer}}""")
    page.wait_for_timeout(1200)
    clock_later=page.evaluate("""()=>({clock:document.getElementById('dashClockLocalText')?.textContent||'',second:document.getElementById('dashClockLocalSecond')?.style.transform||'',sameTimer:!!dashboardClockTimer,countdown:!!pollCountdownTimer})""")
    checks['clock_timer_idempotent']=clock_start['same'] and clock_start['countdown'] and clock_later['sameTimer'] and clock_later['countdown']
    checks['clock_advances_without_backend']=clock_start['second'] != clock_later['second']

    bounded=page.evaluate("""async()=>{let old=window.pywebview.api,calls=0;window.pywebview.api={hung_read:()=>{calls++;return new Promise(()=>{})}};let t=Date.now(),results=await Promise.all([callReadBounded('hung_read',[],{key:'audit-hung',component:'Audit hung',timeoutMs:80}),callReadBounded('hung_read',[],{key:'audit-hung',component:'Audit hung',timeoutMs:80})]);window.pywebview.api=old;return {calls,elapsed:Date.now()-t,timed:results.every(x=>x?.timed_out===true)}}""")
    checks['bounded_read_single_flight']=bounded['calls']==1 and bounded['timed'] and bounded['elapsed']<500

    refresh_recovery=page.evaluate("""async()=>{let old=loadDashboardOverview;loadDashboardOverview=async()=>{throw new Error('audit failure')};await manualDashboardRefresh();let btn=document.getElementById('dashRefreshBtn'),feedback=document.getElementById('dashActionFeedback')?.textContent||'';loadDashboardOverview=old;return {disabled:!!btn?.disabled,text:btn?.textContent||'',feedback}}""")
    checks['manual_refresh_finally_recovers']=not refresh_recovery['disabled'] and 'Refresh failed' in refresh_recovery['feedback']

    activate(page,'dashboard')
    dash=page.evaluate("""()=>{let d=document.getElementById('dashboard'),r=d.getBoundingClientRect();let kids=[...d.children].filter(x=>getComputedStyle(x).display!=='none').map(x=>{let q=x.getBoundingClientRect();return {cls:x.className,top:q.top,bottom:q.bottom,h:q.height}});let gaps=[];for(let i=1;i<kids.length;i++)gaps.push(kids[i].top-kids[i-1].bottom);return {bodyH:document.body.scrollHeight,bodyW:document.body.scrollWidth,vh:innerHeight,vw:innerWidth,dashH:r.height,dashBottom:r.bottom,gaps,kids}}""")
    checks['dashboard_fits']=dash['bodyH']<=dash['vh']+1 and dash['bodyW']<=dash['vw']+1 and dash['dashBottom']<=dash['vh']+1
    # At least 6px between major visible siblings; zero/negative indicates squashed overlap.
    checks['dashboard_spacing']=all(g>=6 for g in dash['gaps'] if g < 200)
    page.screenshot(path=str(shots/'dashboard.png'),full_page=True)

    # 0.9.36 Accounts is observation-only: readiness, money now, venue status and activity.
    activate(page,'accounts')
    sim_payload="""()=>{renderAccountsPage092({ok:true,mode:'sim',period:'30D',current:{currency:'GBP',available:500,exposure:20,balance:520,connected_providers:2,configured_providers:2,total_providers:3,venue_accounts:2,compatible:true},providers:[{provider_id:'betfair',display_name:'Betfair',account_nickname:'Main Betfair',currency:'GBP',available:250,exposure:10,equity:260,balance:260,sim_feed_enabled:true,sim_account_enabled:true,live_feed_enabled:false,live_account_enabled:true},{provider_id:'matchbook',display_name:'Matchbook',account_nickname:'Main Matchbook',currency:'GBP',available:250,exposure:10,equity:260,balance:260,sim_feed_enabled:true,sim_account_enabled:true,live_feed_enabled:false,live_account_enabled:true},{provider_id:'smarkets',display_name:'Smarkets',account_nickname:'Smarkets',integration_pending:true,connection_state:'awaiting_api_access',sim_feed_enabled:false,sim_account_enabled:false,live_feed_enabled:false,live_account_enabled:false,error:'Awaiting API access'}],activity:[{created_at:new Date().toISOString(),exchange:'betfair',action:'credit',amount:25,resulting_equity:260,currency:'GBP',reason:'audit'}],reconciliation:{status:'RECONCILED',difference:0},operations:{scanner:{state:'healthy',last_age_seconds:3},feeds:[{key:'betfair',provider_id:'betfair',exchange:'Betfair',api_state:'available',state:'connected',sim_feed_enabled:true,live_feed_enabled:false,age_seconds:3,latency_ms:128},{key:'matchbook',provider_id:'matchbook',exchange:'Matchbook',api_state:'available',state:'connected',sim_feed_enabled:true,live_feed_enabled:false,age_seconds:5,latency_ms:210},{key:'smarkets',provider_id:'smarkets',exchange:'Smarkets',api_state:'awaiting_api_access',state:'awaiting_api_access',sim_feed_enabled:false,live_feed_enabled:false}]},page_read_only:true})}"""
    page.evaluate(sim_payload)
    accounts_sim=page.evaluate("""()=>({cards:document.querySelectorAll('#accountsProviderGrid .accounts-provider-status0932').length,pending:document.querySelectorAll('#accountsProviderGrid .accounts-provider-status0932.pending').length,text:document.getElementById('accounts')?.innerText||'',controls:document.querySelectorAll('#accounts input,#accounts select').length,buttons:[...document.querySelectorAll('#accounts button')].map(x=>x.textContent.trim()),bodyW:document.body.scrollWidth,vw:innerWidth,reconHidden:document.getElementById('accountsReconciliation')?.hidden})""")
    checks['accounts_sim_observation_only']=accounts_sim['cards']==3 and accounts_sim['pending']==1 and accounts_sim['controls']==0 and all(x in accounts_sim['text'] for x in ['Operational readiness','Money now','Venue status','Account transactions','SIM · VIRTUAL','AWAITING API ACCESS']) and accounts_sim['reconHidden'] and not any('Enable' in x or 'Funding' in x or 'Credentials' in x for x in accounts_sim['buttons'])
    checks['accounts_sim_no_horizontal_scroll']=accounts_sim['bodyW']<=accounts_sim['vw']+1
    page.screenshot(path=str(shots/'accounts-sim.png'),full_page=True)
    page.evaluate("""()=>{document.body.dataset.dataMode='live';renderAccountsPage092({ok:true,mode:'live',period:'30D',current:{currency:'GBP',available:1175,exposure:75,balance:1250,connected_providers:2,configured_providers:2,total_providers:3,compatible:true},providers:[{provider_id:'betfair',display_name:'Betfair',account_nickname:'Main Betfair',currency:'GBP',available:925,exposure:75,balance:1000,connection_state:'connected',live_feed_enabled:true,live_account_enabled:true,sim_feed_enabled:true,sim_account_enabled:true,last_updated:new Date().toISOString()},{provider_id:'matchbook',display_name:'Matchbook',account_nickname:'Main Matchbook',currency:'GBP',available:250,exposure:0,balance:250,connection_state:'connected',live_feed_enabled:true,live_account_enabled:true,sim_feed_enabled:true,sim_account_enabled:true,last_updated:new Date().toISOString()},{provider_id:'smarkets',display_name:'Smarkets',account_nickname:'Smarkets',integration_pending:true,connection_state:'awaiting_api_access',live_feed_enabled:false,live_account_enabled:false,sim_feed_enabled:false,sim_account_enabled:false,error:'Awaiting API access'}],activity:[],reconciliation:{status:'UNAVAILABLE',reason:'Insufficient provider accounting evidence'},operations:{scanner:{state:'healthy',last_age_seconds:2},feeds:[{key:'betfair',provider_id:'betfair',exchange:'Betfair',api_state:'available',state:'connected',sim_feed_enabled:true,live_feed_enabled:true,age_seconds:2,latency_ms:140},{key:'matchbook',provider_id:'matchbook',exchange:'Matchbook',api_state:'available',state:'connected',sim_feed_enabled:true,live_feed_enabled:true,age_seconds:4,latency_ms:205},{key:'smarkets',provider_id:'smarkets',exchange:'Smarkets',api_state:'awaiting_api_access',state:'awaiting_api_access',sim_feed_enabled:false,live_feed_enabled:false}]},page_read_only:true,read_only:true,isolated_from_sim:true})}""")
    accounts_live=page.evaluate("""()=>({cards:document.querySelectorAll('#accountsProviderGrid .accounts-provider-status0932').length,pending:document.querySelectorAll('#accountsProviderGrid .accounts-provider-status0932.pending').length,text:document.getElementById('accounts')?.innerText||'',controls:document.querySelectorAll('#accounts input,#accounts select').length,bodyW:document.body.scrollWidth,vw:innerWidth,reconHidden:document.getElementById('accountsReconciliation')?.hidden,visible:getComputedStyle(document.getElementById('accounts')).display})""")
    checks['accounts_live_actual_only']=accounts_live['cards']==3 and accounts_live['pending']==1 and accounts_live['controls']==0 and 'LIVE · ACTUAL ONLY' in accounts_live['text'] and 'Actual LIVE provider/account state only' in accounts_live['text'] and 'AWAITING API ACCESS' in accounts_live['text'] and not accounts_live['reconHidden']
    checks['accounts_live_no_horizontal_scroll']=accounts_live['bodyW']<=accounts_live['vw']+1 and accounts_live['visible']!='none'
    page.screenshot(path=str(shots/'accounts-live.png'),full_page=True)
    page.evaluate("document.body.dataset.dataMode='sim'")

    # 0.9.5 has one global mode control, preserves the current route, changes the
    # shell synchronously, and discards late opposite-mode account responses.
    mode_controls=page.evaluate("""()=>({groups:document.querySelectorAll('.global-data-mode').length,buttons:document.querySelectorAll('.global-data-mode button').length,dashboardModeButtons:document.querySelectorAll('#dashboard [onclick*=\"setGlobalDataMode\"]').length,adminModeButtons:document.querySelectorAll('#settings [onclick*=\"setGlobalDataMode\"]').length})""")
    checks['single_global_mode_control']=mode_controls['groups']==1 and mode_controls['buttons']==2 and mode_controls['dashboardModeButtons']==0 and mode_controls['adminModeButtons']==0
    activate(page,'sports-config')
    immediate=page.evaluate("""()=>{initialiseDataModeShell('sim');let before=activePageId();setGlobalDataMode('live');return {before,after:activePageId(),mode:dataContextMode,body:document.body.dataset.dataMode,header:document.getElementById('headerMode')?.textContent||''}}""")
    checks['mode_shell_immediate_route_preserved']=immediate['before']=='sports-config' and immediate['after']=='sports-config' and immediate['mode']=='live' and immediate['body']=='live' and 'LIVE' in immediate['header']
    rapid=page.evaluate("""()=>{initialiseDataModeShell('sim');setGlobalDataMode('live');setGlobalDataMode('sim');setGlobalDataMode('live');setGlobalDataMode('sim');return {mode:dataContextMode,body:document.body.dataset.dataMode,route:activePageId()}}""")
    checks['rapid_mode_switch_final_context']=rapid['mode']=='sim' and rapid['body']=='sim' and rapid['route']=='sports-config'

    # 0.9.11 account-context strips are economic state and follow the selected mode.
    # A slow SIM response cannot paint over a later LIVE request.
    activate(page,'sports-config')
    sports_config_basis=page.evaluate("""()=>({strips:document.querySelectorAll('#sports-config .account-basis-strip').length,text:document.getElementById('sports-config')?.innerText||''})""")
    checks['sports_config_no_account_money0937']=sports_config_basis['strips']==0 and 'Sports risk/account basis' not in sports_config_basis['text']
    activate(page,'monitor')
    basis_race=page.evaluate("""async()=>{let old=window.pywebview.api;window.pywebview.api={account_overview:async d=>{await new Promise(r=>setTimeout(r,d.mode==='sim'?80:5));let live=d.mode==='live';return {ok:true,mode:d.mode,currency:'GBP',accounts:{betfair:{exchange:'betfair',display_name:'Betfair',currency:'GBP',available:live?999:111,reserved:0,equity:live?999:111,allocations:[]}},reconciliation:{status:'RECONCILED',delta:0}}}};initialiseDataModeShell('sim');let a=loadAccountBasisSection('monitor');initialiseDataModeShell('live');let b=loadAccountBasisSection('monitor');await Promise.all([a,b]);let text=document.querySelector('#monitor .account-basis-strip')?.innerText||'';window.pywebview.api=old;return {mode:dataContextMode,text}}""")
    checks['account_basis_mode_race_isolated']=basis_race['mode']=='live' and 'LIVE provider accounts' in basis_race['text'] and '£999.00' in basis_race['text'] and '£111.00' not in basis_race['text']

    # 0.9.8: LIVE changes data ownership/capabilities, never route availability.
    # Exercise every normal route/pane with the LIVE shell active and prove the
    # existing page structure remains renderable instead of being replaced by a
    # generic LIVE overlay or hidden wholesale.
    page.evaluate("initialiseDataModeShell('live')")
    live_route_specs=[
        ('dashboard',None),('accounts',None),('activebets',None),
        ('sports',None),('monitor',None),('sports-config',None),
        ('racing',None),('racing-monitor',None),('racing-config',None),
        ('analytics','performance'),('analytics','results'),('analytics','market'),
        ('analytics','replay'),('analytics','scenarios'),('analytics','execution'),
        ('settings',None),('help',None),
    ]
    live_route_visibility={}
    for route,pane in live_route_specs:
        activate(page,route,pane)
        live_route_visibility[f"{route}:{pane or '-'}"]=page.evaluate("""([route,pane])=>{
            const root=document.getElementById(route);
            const target=pane?document.querySelector(`.analytics-pane[data-analytics-pane=\"${pane}\"]`):root;
            if(!root||!target)return false;
            const rr=root.getBoundingClientRect(), tr=target.getBoundingClientRect();
            return root.classList.contains('active') && getComputedStyle(root).display!=='none' &&
                   (!pane || target.classList.contains('active')) && getComputedStyle(target).display!=='none' &&
                   rr.width>100 && rr.height>20 && tr.width>100 && tr.height>20;
        }""",[route,pane])
    checks['live_all_normal_routes_available']=all(live_route_visibility.values())
    checks['live_no_generic_panel_any_route']=page.evaluate("()=>document.querySelectorAll('.live-mode-panel').length===0")
    live_scan_visibility=page.evaluate("""()=>{activate=document.getElementById('dashboard');const b=document.getElementById('dashScanBtn');return !!b&&getComputedStyle(b).display!=='none'&&!b.hidden}""")
    checks['live_manual_scan_control_available']=live_scan_visibility
    page.evaluate("initialiseDataModeShell('sim')")
    # Let any queued route work finish before installing controlled deferred responses.
    page.wait_for_timeout(20)
    activate(page,'dashboard')
    late_live=page.evaluate("""async()=>{lastSimAccountOverview=null;lastLiveAccountOverview=null;initialiseDataModeShell('live');let resolveLive;window.__v094OldApi=window.pywebview.api;window.pywebview.api={account_overview:()=>new Promise(r=>{resolveLive=r})};let pending=loadAccountContext('live',false);initialiseDataModeShell('sim');resolveLive({ok:true,mode:'live',accounts:{betfair:{provider_id:'betfair',display_name:'LIVE-SENTINEL',currency:'GBP',available:9999,exposure:0,equity:9999,mode:'live',connection_state:'connected',freshness:'CURRENT'}}});await pending;await Promise.resolve();return {mode:dataContextMode,text:document.getElementById('dashboardExchangeAccounts')?.innerText||''}}""")
    checks['late_live_response_blocked']=late_live['mode']=='sim' and 'LIVE-SENTINEL' not in late_live['text'] and '9,999' not in late_live['text']
    late_sim=page.evaluate("""async()=>{initialiseDataModeShell('sim');let resolveSim;window.pywebview.api={account_overview:()=>new Promise(r=>{resolveSim=r})};let pending=loadAccountContext('sim',false);initialiseDataModeShell('live');resolveSim({ok:true,mode:'sim',accounts:{betfair:{provider_id:'betfair',display_name:'SIM-SENTINEL',currency:'GBP',available:8888,exposure:0,equity:8888,mode:'sim'}}});await pending;await Promise.resolve();return {mode:dataContextMode,text:document.getElementById('dashboardExchangeAccounts')?.innerText||''}}""")
    checks['late_sim_response_blocked']=late_sim['mode']=='live' and 'SIM-SENTINEL' not in late_sim['text'] and '8,888' not in late_sim['text']
    # Restore harmless proxy semantics for the rest of the render suite.
    page.evaluate("""()=>{window.pywebview.api=window.__v094OldApi;initialiseDataModeShell('sim')}""")

    # 0.9.8 removes the generic LIVE decision panel. LIVE retains the native
    # route UI and page-native evidence only.
    activate(page,'dashboard')
    live_page=page.evaluate("""()=>{initialiseDataModeShell('live');ensureLiveModePanel('dashboard');let d=document.getElementById('dashboard');let visible=[...d.children].filter(x=>getComputedStyle(x).display!=='none');return {mode:dataContextMode,normal:visible.filter(x=>!x.classList.contains('live-mode-panel')).length,panel:document.querySelectorAll('.live-mode-panel').length,scan:getComputedStyle(document.getElementById('dashScanBtn')).display,titleCount:[...d.querySelectorAll('h1,h2')].filter(x=>x.textContent.trim()==='Dashboard').length}}""")
    checks['live_native_dashboard_no_generic_panel']=live_page['mode']=='live' and live_page['normal']>=5 and live_page['panel']==0 and live_page['scan']!='none' and live_page['titleCount']==1
    page.screenshot(path=str(shots/'live-native-dashboard.png'),full_page=True)

    # Racing Config draft ownership: background hydration cannot overwrite a dirty
    # operator draft, but normal hydration resumes after the draft is cleared.
    activate(page,'racing-config')
    racing_dirty=page.evaluate("""()=>{let el=document.getElementById('racingMinProfit');el.value='123.45';racingConfigDirty=true;hydrateRacingConfigValues({racingMinProfit:0},{greyhounds:false,monitor:false});let dirtyValue=el.value;racingConfigDirty=false;hydrateRacingConfigValues({racingMinProfit:7.25},{greyhounds:true,monitor:true});return {dirtyValue,cleanValue:el.value,dirty:racingConfigDirty}}""")
    checks['racing_dirty_draft_survives_hydration']=racing_dirty['dirtyValue']=='123.45' and racing_dirty['cleanValue']=='7.25' and not racing_dirty['dirty']

    # Shared date/time control uses one anchored implementation. Selecting Custom
    # in Replay must not push the review shell down the page.
    activate(page,'analytics','replay')
    datetime=page.evaluate("""()=>{let period=document.getElementById('timelineReplayPeriod'),review=document.querySelector('.replay-review-shell');let before=review.getBoundingClientRect().top;period.value='custom';timelineReplayPeriodChanged();let after=review.getBoundingClientRect().top,box=document.getElementById('timelineReplayCustomRange');return {before,after,active:box.classList.contains('active'),shared:document.querySelectorAll('.shared-datetime-range').length,position:getComputedStyle(box).position}}""")
    checks['shared_datetime_no_replay_layout_shift']=abs(datetime['after']-datetime['before'])<1 and datetime['active'] and datetime['shared']>=3 and datetime['position']=='absolute'

    # Results is domain-owned navigation while Market Analysis remains global.
    results_nav=page.evaluate("""()=>{let analyticsResults=[...document.querySelectorAll('[data-nav-child="analytics"]')].filter(x=>x.textContent.trim()==='Results').length,sports=[...document.querySelectorAll('[data-results-domain="sports"]')].length,racing=[...document.querySelectorAll('[data-results-domain="racing"]')].length,market=[...document.querySelectorAll('[data-nav-child="analytics"]')].filter(x=>x.textContent.includes('Market Analysis')).length;openDomainResults('racing');let rTitle=document.getElementById('positionResultsTitle')?.textContent||'',rSportHidden=document.getElementById('positionResultsSportWrap')?.hidden;openDomainResults('sports');let sTitle=document.getElementById('positionResultsTitle')?.textContent||'',sSportHidden=document.getElementById('positionResultsSportWrap')?.hidden;return {analyticsResults,sports,racing,market,rTitle,rSportHidden,sTitle,sSportHidden}}""")
    checks['results_domain_navigation']=results_nav['analyticsResults']==0 and results_nav['sports']==1 and results_nav['racing']==1 and results_nav['market']==1 and results_nav['rTitle']=='Racing Settled Positions' and results_nav['rSportHidden'] and results_nav['sTitle']=='Sports Settled Positions' and not results_nav['sSportHidden']

    # Execution Analysis in LIVE is a normal page with an honest empty actual
    # execution dataset. Decision simulation must not become an execution row.
    activate(page,'analytics','execution')
    live_exec=page.evaluate("""async()=>{initialiseDataModeShell('live');executionAnalysisDomain='sports';let old=window.pywebview.api;window.pywebview.api={live_execution_activity:async()=>({ok:true,mode:'live',domain:'sports',rows:[],metrics:{attempted:0,submitted:0,filled:0,partial:0,cancelled:0,failed:0,positions:0,settled:0},orders_write_capability:false,live_execution_allowed:false,empty:true,message:'No LIVE execution activity recorded.'}),live_view_data:async()=>({ok:true,mode:'live',capabilities:{balances:true,market_observations:true,decision_evidence:true,order_placement:false},decision_evidence:{summary:{observed:2,qualified:1,execution_grade:0,simulated_fills:1,expected_profit_sum:.12,average_decision_ms:1.1},latest:[]}})};await loadLiveExecutions();let pane=document.querySelector('.analytics-pane[data-analytics-pane="execution"]');let row=document.getElementById('executionsRows')?.innerText||'';let count=document.getElementById('execViewCount')?.textContent||'';window.pywebview.api=old;return {visible:pane&&getComputedStyle(pane).display!='none',row,count,text:pane?.innerText||'',bodyW:document.body.scrollWidth,vw:innerWidth}}""")
    checks['live_execution_analysis_empty_actual_state']=live_exec['visible'] and live_exec['count']=='0' and 'No actual LIVE execution activity.' in live_exec['row'] and 'Decision simulations are separate evidence' in live_exec['row'] and live_exec['bodyW']<=live_exec['vw']+1
    page.screenshot(path=str(shots/'live-execution-empty.png'),full_page=True)

    # 0.9.36 Performance: filters are owned by the Analytics title row.
    activate(page,'analytics','performance')
    page.evaluate("showAnalyticsPane('performance')")
    page.wait_for_timeout(40)
    performance_header=page.evaluate("""()=>{let host=document.querySelector('.performance-header-filter-host0930'),title=document.getElementById('analyticsTitle').getBoundingClientRect(),refresh=document.getElementById('analyticsRefresh').getBoundingClientRect(),filters=host.getBoundingClientRect();return {parent:host.parentElement?.id||'',visible:getComputedStyle(host).display!='none',titleRight:title.right,filterLeft:filters.left,filterRight:filters.right,refreshLeft:refresh.left,bodyW:document.body.scrollWidth,vw:innerWidth}}""")
    checks['performance_filters_in_header0930']=performance_header['parent']=='analyticsContextControls' and performance_header['visible'] and performance_header['filterLeft']>=performance_header['titleRight']-2 and performance_header['filterRight']<=performance_header['refreshLeft']+1 and performance_header['bodyW']<=performance_header['vw']+1

